consumers={}
for root,dirs,files in os.walk('.'):
    dirs[:]=[d for d in dirs if d not in skip_dirs and not d.startswith('build')]
    for f in files:
        if not f.endswith(exts): continue
        fp=os.path.join(root,f)
        # exclude: backend route definitions, tests, docs, contracts, openapi
        norm=fp.replace('./','')
        if norm.startswith(('src/industrial_ops_agent/api/routes/','tests/','docs/','contracts/')): continue
        if norm.startswith('web/.next'): continue
        try: txt=open(fp,encoding='utf-8',errors='ignore').read()
        except: continue
        for m in pat.findall(txt):
            p=m[1:].split('$')[0]
            consumers.setdefault(p,set()).add(fp)
def canon(p): return re.sub(r'\{[^}]+\}','{x}',p)
cons={}
for p,fs in consumers.items():
    cons.setdefault(canon(p),set()).update(fs)
missing=[p for p in paths if canon(p) not in cons]
print("TOTAL",len(paths),"NO-EXTERNAL-CONSUMER",len(missing))
for p in missing: print(p)
