weak=[]
for path in paths:
    if '{' not in path: continue
    segs=path.split('/')
    static=[]
    for s in segs[1:]:
        if s.startswith('{'): break
        static.append(s)
    prefix='/'+'/'.join(static)
    if not prefix or prefix=='/api/v1': 
        weak.append((path,'no-static-prefix'))
